ctive": true}, {"id": "ad88c70a-bf15-4088-904c-dd9d9a9ada72", "color": "Rose Gold", "color_hex": "#d18d9e", "size": "Travel set", "stock": 21, "active": true}]}]$catalog$::jsonb;
 item jsonb; media jsonb; variant jsonb; category_id uuid; product_id uuid;
BEGIN
 IF jsonb_array_length(catalog)<>50 THEN RAISE EXCEPTION 'Expected fifty demo products'; END IF;
 IF (SELECT count(*) FROM public.categories WHERE slug IN ('lip-gloss','lip-oils','lip-cheek-tints','lip-balms','beauty-essentials') AND is_active)<>5 THEN
  RAISE EXCEPTION 'A required active demo category is missing';
 END IF;
 FOR item IN SELECT * FROM jsonb_array_elements(catalog) LOOP
  product_id:=(item->>'id')::uuid;
  IF EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id) THEN
   IF NOT EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND p.name LIKE '% · Demo') THEN
    RAISE EXCEPTION 'Seed ID belongs to a real product';
   END IF;
   CONTINUE;
  END IF;
  SELECT c.id INTO STRICT category_id FROM public.categories c WHERE c.slug=item->>'category_slug' AND c.is_active;
  INSERT INTO public.products(id,category_id,name,description,care,price_cents,status,featured,department)
  VALUES(product_id,category_id,item->>'name',item->>'description',item->>'care',(item->>'price_cents')::int,'published',(item->>'featured')::boolean,'unisex');
  FOR variant IN SELECT * FROM jsonb_array_elements(item->'variants') LOOP
   INSERT INTO public.product_variants(id,product_id,color,color_hex,size,stock,active)
   VALUES((variant->>'id')::uuid,product_id,variant->>'color',variant->>'color_hex',variant->>'size',(variant->>'stock')::int,true);
  END LOOP;
  FOR media IN SELECT * FROM jsonb_array_elements(item->'images') LOOP
   INSERT INTO public.product_images(product_id,path,alt,position)
   VALUES(product_id,media->>'path',media->>'alt',(media->>'position')::int);
  END LOOP;
 END LOOP;
END $demo_seed$;
